contract InvMutTest {
    C c;
    uint256 util;
    bool indexDone;

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 u) public {
        util = u;
        indexDone = false;
        bool reverted;
        uint256 ret;
        try c.rate(address(this), asset) returns (uint256 r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }
        assert(reverted ? (u == 0) : (u > 0 && ret == 0));
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        if (!indexDone) {
            // first callback: currentUtilizationIndex(_asset)
            indexDone = true;
            return abi.encode(uint256(0));
        }
        // second callback: utilization(_asset)
        return abi.encode(util);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        require(kink <= 2e27);
        c.initialize(address(this));
        bool reverted;
        IVaultAdapter.SlopeData memory s = IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        try c.setSlopes(asset, s) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (kink == 0 || kink >= 1e27));
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // c.initialize and the checkAccess modifier call back into this contract;
        // checkAccess(_selector, _contract, _caller) must return true.
        return abi.encode(true);
    }

    receive() external payable {}
}

