contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _vault, address _asset) public {
        bool succeeded = false;
        bool customError = false;
        bool panicked = false;

        // On a fresh C the stored slope data is zero, so slopes.kink == 0.
        // _applySlopes evaluates (1e27 * (slopes.kink - _utilization)) / slopes.kink,
        // which is a division by zero and must panic — never return normally
        // and never revert with a custom error.
        try c.rate(_vault, _asset) {
            succeeded = true;
        } catch Panic(uint256) {
            panicked = true;
        } catch {
            customError = true;
        }

        assert(!succeeded && !customError && panicked);
    }

    receive() external payable {}
}

