contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 kink, uint256 slope0, uint256 slope1) public {
        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });
        bool reverted;
        bytes memory returndata;
        try c.setSlopes(address(this), slopes) {
            reverted = false;
        } catch (bytes memory data) {
            reverted = true;
            returndata = data;
        }
        if (!reverted) {
            // Successful path: kink must be strictly within (0, 1e27).
            assert(kink > 0 && kink < 1e27);
        } else {
            // Reverted path: must be an InvalidKink revert caused by the bad kink.
            assert(kink == 0 || kink >= 1e27);
        }
    }
}

